def f(i, x):
    x=np.asarray(x,dtype=float)
    names,coefs=SPEC[i]
    z=np.zeros(len(x))
    for n,c in zip(names,coefs): z=z+c*_F(x,n)
    out=np.maximum(z,0)
    if i==16: out=np.where(x.max(1)<0,out,0.0)
    return out
